export function conversationQuietHours(channel:{quiet_start:number;quiet_end:number;time_zone:string},now=new Date()):boolean{if(channel.quiet_start===channel.quiet_end)return false;const hour=Number(new Intl.DateTimeFormat('en',{timeZone:channel.time_zone,hour:'2-digit',hourCycle:'h23'}).format(now));return channel.quiet_start<channel.quiet_end?hour>=channel.quiet_start&&hour<channel.quiet_end:hour>=channel.quiet_start||hour<channel.quiet_end;}
