export async function cancelConversationAutomation(c:PoolClient,organizationId:string,conversationId:string,reason:string):Promise<number>{
 const rows=(await c.query("UPDATE conversation_outbox SET state='cancelled',last_error=$3,updated_at=clock_timestamp() WHERE organization_id=$1 AND conversation_id=$2 AND origin IN('ai','automation') AND state IN('queued','sent') RETURNING message_id,to_jsonb(conversation_outbox)->>'automation_job_id' AS automation_job_id",[organizationId,conversationId,reason])).rows;
 if(rows.length)await c.query("UPDATE conversation_messages SET status='cancelled' WHERE organization_id=$1 AND id=ANY($2::uuid[])",[organizationId,rows.map(r=>r.message_id)]);const jobs=rows.map(r=>r.automation_job_id).filter(Boolean);if(jobs.length)await c.query("UPDATE automation_jobs SET status='cancelled',last_error=$3,updated_at=clock_timestamp() WHERE organization_id=$1 AND id=ANY($2::uuid[]) AND status='queued'",[organizationId,jobs,reason]);return rows.length;
}

/** Reusable server-only publication authority; no browser chooses the publishing identity. */
export async function publicConversationChannelAccess(c:PoolClient,config:ServerConfig,id:string):Promise<{channel:Row;actor:AuthUser}>{
  const r=(await c.query("SELECT ch.*,p.name AS property_name,u.email,u.display_name,m.role,o.name AS organization_name,ARRAY(SELECT permission FROM role_permissions WHERE role_key=m.role) AS permissions FROM conversation_channels ch JOIN properties p ON p.id=ch.property_id AND p.organization_id=ch.organization_id JOIN organization_memberships m ON m.id=ch.published_by_membership_id AND m.organization_id=ch.organization_id AND m.user_id=ch.published_by_user_id AND m.active AND m.account_kind='staff' JOIN users u ON u.id=m.user_id AND u.active AND u.account_kind='staff' JOIN organizations o ON o.id=m.organization_id WHERE ch.id=$1 AND ch.enabled AND EXISTS(SELECT 1 FROM role_permissions rp WHERE rp.role_key=m.role AND rp.permission='leasing.manage') AND (m.role='organization_admin' OR EXISTS(SELECT 1 FROM property_access_assignments pa WHERE pa.organization_id=ch.organization_id AND pa.property_id=ch.property_id AND pa.membership_id=m.id)) FOR SHARE OF ch,m,u",[id])).rows[0];
  if(!r)throw new ApiError(410,'CHANNEL_UNAVAILABLE','This public property channel is not configured or is no longer authorized.');
  if(config.demoMode)await requireIsolatedDemo(config,c);else if(r.mode!=='native')throw new ApiError(410,'CHANNEL_REPUBLICATION_REQUIRED','The property team must publish this website chat for the current application.');
  const actor:AuthUser={id:r.published_by_user_id,name:r.display_name,email:r.email,membershipId:r.published_by_membership_id,sessionExpiresAt:new Date(Date.now()+3600000).toISOString(),permissions:r.permissions as Permission[],organization:{id:r.organization_id,name:r.organization_name,role:r.role as OrganizationRole}};return{channel:r,actor};
}
export const voiceConversationOutcomes={"started":"A local voice simulation started; no phone call or audio recording was made.","question_answered":"The local voice assistant provided approved public property guidance.","viewing_requested":"The local caller requested viewing options; no booking is implied.","viewing_booked":"The native calendar service confirmed a viewing for this local voice session.","application_guidance":"Verified portal next-step guidance was provided; private details are not copied to this conversation.","handoff_requested":"Staff assistance was requested for this local voice session; no telephone transfer is confirmed.","transfer_failed":"The local voice session could not confirm a staff transfer.","provider_failed":"A provider-unavailable condition was simulated; no phone call was attempted.","interrupted":"The local transcript session was interrupted.","timed_out":"The local transcript session timed out.","ended":"The local voice simulation ended.","slot_unavailable":"The requested viewing slot could not be confirmed."} as const;
