 async approve(u:AuthUser,digest:string,id:string,messageId:string,input:{requestKey:string;body?:string}):Promise<ConversationDetail>{await this.db.transaction(async c=>{const r=await this.staff(c,u,digest,id,true);if(!r.consent)throw new ApiError(409,'CONSENT_REQUIRED','Customer consent is required before queuing a local reply.');await this.receipt(c,u.organization.id,'staff:'+u.id,input.requestKey,'approve',{id,messageId,...input},async()=>{const m=(await c.query("SELECT * FROM conversation_messages WHERE id=$1 AND conversation_id=$2 AND role='draft' FOR UPDATE",[messageId,id])).rows[0];if(!m)unavailable();if(m.status!=='proposed')throw new ApiError(409,'DRAFT_ALREADY_APPROVED','This draft was already approved.');await c.query("UPDATE customer_conversations SET ownership='staff_handling' WHERE id=$1",[id]);await cancelConversationAutomation(c,u.organization.id,id,'staff_takeover');await c.query("UPDATE conversation_messages SET role='staff',body=$2,status='queued',actor_user_id=$3 WHERE id=$1",[messageId,input.body??m.body,u.id]);await c.query("INSERT INTO conversation_outbox(organization_id,conversation_id,message_id,origin,provider) VALUES($1,$2,$3,'staff',$4)",[u.organization.id,id,messageId,r.mode==='native'?'native_website':'local_simulator']);await this.event(c,r,u,'draft_approved','Staff approved a local reply draft; delivery remains separate.');return{messageId};});});return this.detail(u,digest,id,{page:1,pageSize:50});}
 private async deliver(c:PoolClient,r:Row,outcome:'sent'|'delivered'|'temporary_failure',interactive=false):Promise<void>{
  const {channel}=await this.publisher(c,r.channel_id),isolated=await isIsolatedDemo(this.config,c),rows=(await c.query("SELECT * FROM conversation_outbox WHERE conversation_id=$1 AND state IN('queued','sent') AND next_attempt_at<=clock_timestamp() ORDER BY created_at,id LIMIT 20 FOR UPDATE",[r.id])).rows;
  const organizationPolicy=await organizationDeliveryPolicy(c,r.organization_id);
  for(const o of rows){
   if(o.automation_job_id&&!await(await import('./automations.js')).validateAutomationOutbox(c,this.config,o))continue;
   if(!r.consent&&!(interactive&&o.requested_response)||o.origin!=='staff'&&r.ownership!=='ai_active'){await c.query("UPDATE conversation_outbox SET state='cancelled',last_error=$2 WHERE id=$1",[o.id,!r.consent?'consent_withdrawn':'staff_takeover']);await c.query("UPDATE conversation_messages SET status='cancelled' WHERE id=$1",[o.message_id]);continue;}
   if(o.origin==='ai'){try{await assertAiCapability(c,this.config,r.organization_id,'native_read',undefined,true);const m=(await c.query('SELECT sources FROM conversation_messages WHERE id=$1 AND organization_id=$2',[o.message_id,r.organization_id])).rows[0];await assertAiKnowledgeCurrent(c,r.organization_id,r.property_id,m?.sources??[],true);}catch(e){if(!(e instanceof ApiError))throw e;await c.query("UPDATE conversation_outbox SET state='cancelled',last_error='assistant_policy_or_knowledge_changed' WHERE id=$1",[o.id]);await c.query("UPDATE conversation_messages SET status='cancelled' WHERE id=$1",[o.message_id]);continue;}}
   if(organizationIsQuiet(organizationPolicy)&&!(interactive&&o.requested_response)){await c.query("UPDATE conversation_outbox SET next_attempt_at=clock_timestamp()+interval '5 minutes' WHERE id=$1",[o.id]);continue;}
   if(conversationQuietHours({quiet_start:channel.quiet_start,quiet_end:channel.quiet_end,time_zone:channel.time_zone})&&!(interactive&&o.requested_response))continue;
   if(r.mode==='native'&&r.origin==='website'&&o.origin==='staff'){
    const message=(await c.query('SELECT actor_user_id FROM conversation_messages WHERE id=$1 AND organization_id=$2',[o.message_id,r.organization_id])).rows[0];
    if(!await nativeStaffReplyAuthorAllowed(c,r.organization_id,r.property_id,r.lead_id,message?.actor_user_id??null)){await c.query("UPDATE conversation_outbox SET state='cancelled',last_error='staff_author_access_changed' WHERE id=$1",[o.id]);await c.query("UPDATE conversation_messages SET status='cancelled' WHERE id=$1",[o.message_id]);continue;}
   }
   const delivery=await conversationTransport('website',r.mode==='native'&&r.origin==='website'?'native_chat':'local_simulation').deliver(o.message_id,outcome,isolated);
   if(outcome==='temporary_failure'){const attempts=o.attempts+1,state=attempts>=3?'failed':'queued';await c.query("UPDATE conversation_outbox SET attempts=$2,state=$3,last_error='simulated_temporary_failure',next_attempt_at=clock_timestamp()+($4*interval '1 second'),updated_at=clock_timestamp() WHERE id=$1",[o.id,attempts,state,Math.min(120,10*2**(attempts-1))]);await c.query('UPDATE conversation_messages SET status=$2 WHERE id=$1',[o.message_id,state==='failed'?'failed':'queued']);}
   else{await c.query("UPDATE conversation_outbox SET state=$2,provider=$4,provider_message_id=COALESCE(provider_message_id,$3),last_error=NULL,updated_at=clock_timestamp() WHERE id=$1",[o.id,outcome,delivery.providerMessageId,delivery.provider]);await c.query('UPDATE conversation_messages SET status=$2 WHERE id=$1',[o.message_id,outcome]);}
   if(o.automation_job_id)await(await import('./automations.js')).recordAutomationDelivery(c,o,outcome);
  }
 }
