   const owner=(await c.query("SELECT m.id FROM organization_memberships m JOIN users u ON u.id=m.user_id AND u.active AND u.account_kind='staff' JOIN viewing_staff_availability va ON va.membership_id=m.id AND va.organization_id=m.organization_id AND va.property_id=$2 AND va.enabled WHERE m.organization_id=$1 AND m.active AND m.account_kind='staff' AND EXISTS(SELECT 1 FROM role_permissions rp WHERE rp.role_key=m.role AND rp.permission='leasing.manage') AND (m.role='organization_admin' OR EXISTS(SELECT 1 FROM property_access_assignments pa WHERE pa.organization_id=m.organization_id AND pa.property_id=$2 AND pa.membership_id=m.id)) ORDER BY m.created_at,m.id LIMIT 1",[r.organization_id,r.property_id])).rows[0];
